/* ---------- France régionale (1/2) : Est, Bourgogne, Lyon, Paris, Nord-Ouest ---------- */
const D40 = [
{ id:'flammekueche', c:'eu', lat:48.462, lon:7.482, base:4, prep:40, cook:10, diff:2, tags:['bread','pork','street'],
  art:{v:'board',bg:'#2f2519',plate:'#f2e6c8',style:'flat',food:['#f4f0e6','#c9a878','#e8d8b8','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Flammekueche',en:'Tarte flambée'},
  p:{fr:'Obernai, Alsace, France',en:'Obernai, Alsace, France'},
  d:{fr:"Une pâte étalée au plus fin, couverte de crème, d'oignons et de lardons, cuite deux minutes contre la sole d'un four à pain. Elle servait à juger la température du four avant d'y enfourner les miches.",
     en:"Dough rolled paper-thin, spread with cream, onion and bacon, and baked for two minutes against the floor of a bread oven. It was used to judge the oven's heat before the loaves went in."},
  i:[['flour',400,'g'],['water',220,'ml'],['olive_oil',3,'tbsp'],['sour_cream',300,'ml'],['fromage_blanc',200,'g'],['onion',3,'pc'],['smoked_bacon',250,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez farine, eau, huile et sel 10 minutes en une pâte souple sans levure, puis laissez-la reposer 30 minutes.","Mêlez la crème aigre et le fromage blanc égoutté, salez, poivrez et muscadez : l'appareil doit être épais, jamais liquide.","Émincez les oignons en fines lamelles et taillez le lard en gros lardons ; ne les cuisez pas, ils cuiront sur la tarte.","Étalez la pâte au rouleau jusqu'à voir la table au travers, sur un rectangle qui tient dans votre four.","Étalez la crème, parsemez oignons et lardons, et enfournez au maximum de votre four, sole chaude, 8 à 10 minutes. Les bords doivent noircir par endroits."],
     en:["Knead flour, water, oil and salt for 10 minutes into a supple yeastless dough, then rest it for 30 minutes.","Mix the sour cream and drained fromage blanc, season with salt, pepper and nutmeg: the mixture must be thick, never runny.","Slice the onions thinly and cut the bacon into large lardons; do not cook them, they cook on the tart.","Roll the dough until you can see the table through it, into a rectangle that fits your oven.","Spread the cream, scatter onion and bacon, and bake in the hottest part of the oven on a hot floor for 8 to 10 minutes. The edges should blacken in places."]} },

{ id:'matelote-au-riesling', c:'eu', lat:48.259, lon:7.454, base:6, prep:40, cook:35, diff:2, tags:['sea','sunday','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e8dcc0','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Matelote au riesling',en:'Riesling matelote'},
  p:{fr:'Sélestat, Alsace, France',en:'Sélestat, Alsace, France'},
  d:{fr:"Quatre poissons de rivière — anguille, brochet, sandre, truite — pochés dans le riesling et nappés d'une sauce à la crème. Les auberges de l'Ill en font depuis toujours leur plat de fête, servi avec des nouilles.",
     en:"Four river fish — eel, pike, zander, trout — poached in Riesling and coated in a cream sauce. The inns along the Ill have long made it their feast dish, served with noodles."},
  i:[['eel',400,'g'],['whitefish',600,'g'],['trout',400,'g'],['riesling',750,'ml'],['shallot',4,'pc'],['button_mushrooms',300,'g'],['heavy_cream',300,'ml'],['butter',100,'g'],['flour',3,'tbsp'],['egg_yolk',2,'pc'],['parsley',4,'tbsp'],['bay_leaf',2,'pc'],['pasta',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites suer les échalotes émincées dans la moitié du beurre, ajoutez le riesling et le laurier, portez à frémissement.","Pochez les poissons du plus ferme au plus fragile — anguille d'abord, truite en dernier — 4 à 8 minutes chacun, puis réservez-les au chaud.","Filtrez le bouillon et faites-le réduire de moitié à feu vif.","Faites un roux avec le beurre restant et la farine, mouillez du bouillon réduit et laissez cuire 8 minutes.","Ajoutez les champignons sautés et la crème, liez aux jaunes hors du feu, nappez les poissons et servez avec des nouilles au beurre."],
     en:["Sweat the sliced shallots in half the butter, add the Riesling and bay, and bring to a simmer.","Poach the fish from firmest to most delicate — eel first, trout last — 4 to 8 minutes each, then keep them warm.","Strain the broth and reduce it by half over high heat.","Make a roux with the remaining butter and the flour, whisk in the reduced broth and cook for 8 minutes.","Add the sautéed mushrooms and the cream, bind with the yolks off the heat, coat the fish and serve with buttered noodles."]} },

{ id:'coq-au-riesling', c:'eu', lat:48.196, lon:7.318, base:6, prep:30, cook:70, diff:2, tags:['poultry','sunday','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e4c8',style:'stew',food:['#f0e8d0','#e8dcb8','#c9a878','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Coq au riesling',en:'Coq au Riesling'},
  p:{fr:'Ribeauvillé, Alsace, France',en:'Ribeauvillé, Alsace, France'},
  d:{fr:"Le cousin blanc du coq au vin : ici le vin est sec et minéral, la sauce reste claire, et les morilles remplacent les lardons. On le sert avec des spätzle, jamais avec des pommes de terre.",
     en:"The white cousin of coq au vin: the wine is dry and mineral, the sauce stays pale, and morels replace the bacon. Served with spätzle, never with potatoes."},
  i:[['chicken',2,'kg'],['riesling',750,'ml'],['dried_morels',40,'g'],['button_mushrooms',300,'g'],['shallot',4,'pc'],['heavy_cream',350,'ml'],['butter',80,'g'],['flour',3,'tbsp'],['brandy',50,'ml'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les morilles une heure dans l'eau tiède ; filtrez soigneusement cette eau et gardez-la.","Faites dorer les morceaux de volaille dans le beurre sans les brûler : la sauce doit rester blonde.","Flambez au marc, singez à la farine, puis versez le riesling et l'eau des morilles.","Ajoutez thym et laurier, couvrez et laissez mijoter 50 minutes à feu doux.","Retirez la volaille, ajoutez la crème et les champignons à la sauce, laissez réduire 10 minutes, puis remettez les morceaux. Servez avec des spätzle."],
     en:["Soak the morels for an hour in warm water; strain that water carefully and keep it.","Brown the chicken pieces in the butter without scorching them: the sauce must stay pale.","Flame with marc, dust with flour, then pour in the Riesling and the morel liquid.","Add thyme and bay, cover and simmer for 50 minutes over low heat.","Lift out the chicken, add the cream and mushrooms to the sauce, reduce for 10 minutes, then return the pieces. Serve with spätzle."]} },

{ id:'bouchee-a-la-reine', c:'eu', lat:48.590, lon:6.494, base:6, prep:45, cook:40, diff:3, tags:['poultry','festive','sunday'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'pastry',food:['#e0b45a','#f0e8d0','#f2dfa8','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Bouchée à la reine',en:'Bouchée à la reine'},
  p:{fr:'Lunéville, Lorraine, France',en:'Lunéville, Lorraine, France'},
  d:{fr:"Un vol-au-vent garni de volaille, de quenelles et de champignons dans une sauce blanche. Il porte le nom de Marie Leszczyńska, reine de France et fille du duc de Lorraine, qui l'aurait fait servir à Versailles.",
     en:"A vol-au-vent filled with chicken, quenelles and mushrooms in a white sauce. It bears the name of Marie Leszczyńska, queen of France and daughter of the Duke of Lorraine, who is said to have had it served at Versailles."},
  i:[['puff_pastry',600,'g'],['chicken_breast',600,'g'],['veal_shoulder',300,'g'],['button_mushrooms',400,'g'],['chicken_broth',800,'ml'],['butter',100,'g'],['flour',80,'g'],['heavy_cream',250,'ml'],['egg_yolk',2,'pc'],['egg',1,'pc'],['lemon',1,'pc'],['nutmeg',1,'pinch'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez douze disques de pâte feuilletée, évidez-en six au centre pour former les couronnes, empilez et dorez à l'œuf.","Enfournez 25 minutes à 200 °C, puis creusez délicatement le chapeau et l'intérieur.","Pochez la volaille et le veau 25 minutes dans le bouillon, puis détaillez-les en dés d'un centimètre.","Faites un velouté avec le beurre, la farine et le bouillon filtré, laissez cuire 15 minutes à feu doux.","Ajoutez les champignons sautés et les viandes, liez aux jaunes battus dans la crème hors du feu, citronnez, et garnissez les croûtes brûlantes."],
     en:["Cut twelve discs of puff pastry, hollow the centre from six of them to make rings, stack and glaze with egg.","Bake for 25 minutes at 200°C, then carefully lift the lid and hollow out the inside.","Poach the chicken and veal for 25 minutes in the broth, then cut into one-centimetre dice.","Make a velouté with the butter, flour and strained broth, and cook it for 15 minutes over low heat.","Add the sautéed mushrooms and the meats, bind with the yolks beaten into the cream off the heat, sharpen with lemon, and fill the scalding cases."]} },

{ id:'gougeres', c:'eu', lat:47.856, lon:3.973, base:8, prep:25, cook:30, diff:2, tags:['cheese','bake','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#f2dfa8','#c98a2c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Gougères',en:'Gougères'},
  p:{fr:'Tonnerre, Bourgogne, France',en:'Tonnerre, Burgundy, France'},
  d:{fr:"De petits choux au comté, servis tièdes à l'apéritif dans toutes les caves de Bourgogne. On les proposait aux acheteurs lors des dégustations : le fromage arrondit le vin et fait paraître les tanins plus souples.",
     en:"Small comté choux buns, served warm as an aperitif in every Burgundy cellar. They were offered to buyers during tastings: the cheese rounds out the wine and makes the tannins seem softer."},
  i:[['water',250,'ml'],['butter',100,'g'],['flour',150,'g'],['egg',4,'pc'],['comte_cheese',150,'g'],['nutmeg',1,'pinch'],['white_pepper',1,'tsp'],['salt',null,'']],
  s:{fr:["Portez l'eau, le beurre et le sel à ébullition, jetez la farine d'un seul coup et remuez vivement.","Desséchez la pâte deux minutes sur le feu, jusqu'à ce qu'elle forme une boule qui se détache de la casserole.","Hors du feu, incorporez les œufs un à un : la pâte doit former un bec souple au bout de la spatule.","Ajoutez les trois quarts du comté râpé, la muscade et le poivre blanc.","Dressez de petits tas espacés, poudrez du fromage restant et enfournez 30 minutes à 180 °C sans ouvrir le four."],
     en:["Bring the water, butter and salt to the boil, tip in the flour all at once and beat briskly.","Dry the paste out for two minutes over the heat, until it forms a ball that leaves the pan.","Off the heat, work in the eggs one at a time: the paste should form a soft beak on the spatula.","Add three quarters of the grated comté, the nutmeg and the white pepper.","Pipe well-spaced mounds, dust with the remaining cheese and bake for 30 minutes at 180°C without opening the oven."]} },

{ id:'oeufs-en-meurette', c:'eu', lat:47.135, lon:4.949, base:4, prep:30, cook:40, diff:2, tags:['comfort','sunday','fast'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#f4f0e6','#8f5a3a','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Œufs en meurette',en:'Œufs en meurette'},
  p:{fr:'Nuits-Saint-Georges, Bourgogne, France',en:'Nuits-Saint-Georges, Burgundy, France'},
  d:{fr:"Des œufs pochés dans le vin rouge, servis sur un croûton sous une sauce aux lardons et aux oignons grelots. Le vin de pochage devient la sauce : rien ne se perd, et le blanc prend une teinte violacée déconcertante.",
     en:"Eggs poached in red wine, served on a crouton under a sauce of lardons and button onions. The poaching wine becomes the sauce: nothing is wasted, and the whites take on a disconcerting purple tint."},
  i:[['egg',8,'pc'],['red_wine',750,'ml'],['smoked_bacon',200,'g'],['pearl_onions',250,'g'],['button_mushrooms',250,'g'],['shallot',3,'pc'],['garlic',3,'clove'],['butter',80,'g'],['flour',2,'tbsp'],['beef_broth',300,'ml'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['rustic_bread',8,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites revenir lardons, oignons grelots et champignons dans le beurre, puis réservez-les.","Faites suer les échalotes, singez à la farine, versez le vin rouge et le bouillon, ajoutez thym et laurier, et laissez réduire 25 minutes.","Filtrez la sauce et gardez-en un bon verre à part, dans une petite casserole, pour pocher les œufs.","Cassez les œufs un à un dans ce vin frémissant et pochez-les 3 minutes ; égouttez-les sur un linge.","Frottez les croûtons grillés à l'ail, posez-y les œufs, nappez de sauce et couvrez de la garniture."],
     en:["Fry the lardons, button onions and mushrooms in the butter, then set them aside.","Sweat the shallots, dust with flour, pour in the red wine and broth, add thyme and bay, and reduce for 25 minutes.","Strain the sauce and set a good glassful aside in a small pan for poaching the eggs.","Break the eggs one at a time into that simmering wine and poach for 3 minutes; drain them on a cloth.","Rub the toasted croutons with garlic, set the eggs on them, coat with sauce and cover with the garnish."]} },

{ id:'jambon-persille', c:'eu', lat:46.306, lon:4.833, base:10, prep:60, cook:180, diff:2, tags:['pork','festive','fresh'],
  art:{v:'board',bg:'#2f3328',plate:'#f2e8d0',style:'flat',food:['#c9604a','#4f8f4a','#f0e8d0','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Jambon persillé',en:'Jambon persillé'},
  p:{fr:'Mâcon, Bourgogne, France',en:'Mâcon, Burgundy, France'},
  d:{fr:"Du jambon cuit à l'os, effiloché et pris dans une gelée au vin blanc et au persil. Terrine de Pâques bourguignonne, dont le vert et le rose se dessinent à la coupe comme un marbre.",
     en:"Ham cooked on the bone, pulled apart and set in a jelly of white wine and parsley. The Burgundian Easter terrine, whose green and pink appear at the cut like marble."},
  i:[['salted_pork',2,'kg'],['veal_foot',1,'pc'],['white_wine',750,'ml'],['carrot',2,'pc'],['onion',2,'pc'],['parsley',3,'bunch'],['garlic',6,'clove'],['shallot',3,'pc'],['white_wine_vinegar',3,'tbsp'],['tarragon',3,'sprig'],['black_peppercorns',1,'tbsp'],['bay_leaf',3,'pc'],['salt',null,'']],
  s:{fr:["Dessalez le jambon 12 heures à l'eau froide, en changeant l'eau trois fois.","Faites-le cuire 3 heures à frémissement avec le pied de veau, le vin blanc, les légumes et les aromates.","Laissez tiédir dans le bouillon, puis effilochez la chair à la main en gros morceaux, sans la hacher.","Filtrez le bouillon, laissez-le refroidir et vérifiez qu'il prend en gelée ; sinon, faites-le réduire davantage.","Alternez dans une terrine jambon et persillade — persil, ail, échalote, estragon —, versez la gelée tiède et pressez une nuit au froid."],
     en:["Desalt the ham for 12 hours in cold water, changing it three times.","Simmer it for 3 hours with the veal foot, white wine, vegetables and aromatics.","Let it cool in the broth, then pull the meat apart by hand into large pieces, without chopping it.","Strain the broth, cool it and check that it sets; if not, reduce it further.","Layer ham and parsley mixture — parsley, garlic, shallot, tarragon — in a terrine, pour over the warm jelly and press overnight in the fridge."]} },

{ id:'poulet-de-bresse-a-la-creme', c:'eu', lat:46.205, lon:5.226, base:6, prep:25, cook:60, diff:2, tags:['poultry','sunday','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e8dcb8','#c9a878','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Poulet de Bresse à la crème',en:'Bresse chicken in cream'},
  p:{fr:'Bourg-en-Bresse, Ain, France',en:'Bourg-en-Bresse, Ain, France'},
  d:{fr:"La seule volaille au monde à porter une appellation d'origine, cuite dans le beurre et noyée de crème d'Étrez. Le plat est d'une simplicité désarmante : c'est la bête qui fait tout le travail.",
     en:"The only poultry in the world with a protected designation of origin, cooked in butter and drowned in Étrez cream. The dish is disarmingly simple: the bird does all the work."},
  i:[['chicken',2,'kg'],['heavy_cream',500,'ml'],['butter',100,'g'],['button_mushrooms',400,'g'],['shallot',3,'pc'],['white_wine',200,'ml'],['vin_jaune',80,'ml'],['lemon',1,'pc'],['tarragon',3,'sprig'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez la volaille en huit, salez-la et laissez-la revenir à la peau dans le beurre mousseux, sans la colorer fortement.","Ajoutez les échalotes émincées, couvrez et laissez étuver 25 minutes à feu très doux.","Retirez les blancs, qui cuisent plus vite, et poursuivez 15 minutes pour les cuisses.","Déglacez au vin blanc, laissez réduire à sec, puis versez la crème et laissez-la napper 10 minutes.","Remettez toute la volaille, ajoutez les champignons sautés, l'estragon et un trait de vin jaune. Citronnez au dernier moment."],
     en:["Joint the bird into eight, salt it and let it colour skin-side down in foaming butter, without browning it hard.","Add the sliced shallots, cover and stew for 25 minutes over very low heat.","Take out the breasts, which cook faster, and continue for 15 minutes with the legs.","Deglaze with white wine, reduce until dry, then pour in the cream and let it coat for 10 minutes.","Return all the chicken, add the sautéed mushrooms, the tarragon and a dash of vin jaune. Sharpen with lemon at the last moment."]} },

{ id:'quenelles-sauce-nantua', c:'eu', lat:46.152, lon:5.607, base:6, prep:60, cook:40, diff:3, tags:['sea','sunday','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#f0a878','#e0703a','#f4f0e6','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Quenelles de brochet, sauce Nantua',en:'Pike quenelles, sauce Nantua'},
  p:{fr:'Nantua, Bugey, France',en:'Nantua, Bugey, France'},
  d:{fr:"Des quenelles de brochet qui gonflent au four jusqu'à tripler de volume, sous une sauce rose au beurre d'écrevisses. Le lac de Nantua fournissait les deux : le poisson et les écrevisses à pattes rouges.",
     en:"Pike quenelles that swell in the oven until they treble in size, under a pink sauce of crayfish butter. Lake Nantua supplied both: the fish and the red-clawed crayfish."},
  i:[['whitefish',500,'g'],['butter',300,'g'],['flour',150,'g'],['whole_milk',400,'ml'],['egg',6,'pc'],['crayfish',800,'g'],['heavy_cream',400,'ml'],['tomato_paste',2,'tbsp'],['brandy',60,'ml'],['shallot',3,'pc'],['carrot',1,'pc'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Préparez une panade : portez le lait et 100 g de beurre à ébullition, jetez la farine, desséchez, puis laissez refroidir complètement.","Mixez la chair de brochet très froide, incorporez la panade puis les œufs un à un, et enfin 100 g de beurre pommade. Réservez 3 heures au froid.","Faites revenir les écrevisses avec échalote et carotte, flambez au marc, ajoutez le concentré, mouillez d'eau et laissez cuire 20 minutes. Filtrez en pressant, puis liez à la crème.","Formez les quenelles à deux cuillères et pochez-les 10 minutes à l'eau frémissante salée : elles doivent remonter.","Rangez-les dans un plat, nappez de sauce Nantua et enfournez 25 minutes à 200 °C. Elles gonflent et dorent."],
     en:["Make a panade: bring the milk and 100 g of butter to the boil, tip in the flour, dry it out, then cool completely.","Blend the very cold pike flesh, work in the panade then the eggs one at a time, and finally 100 g of softened butter. Chill for 3 hours.","Fry the crayfish with shallot and carrot, flame with marc, add the tomato paste, cover with water and cook for 20 minutes. Strain, pressing hard, then enrich with the cream.","Shape the quenelles with two spoons and poach them for 10 minutes in simmering salted water: they should rise.","Arrange them in a dish, coat with the Nantua sauce and bake for 25 minutes at 200°C. They swell and brown."]} },

{ id:'tablier-de-sapeur', c:'eu', lat:45.764, lon:4.836, base:4, prep:40, cook:20, diff:2, tags:['fry','comfort','sunday'],
  art:{v:'plate',bg:'#2f3326',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#f0d89a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Tablier de sapeur',en:'Tablier de sapeur'},
  p:{fr:'Lyon, France',en:'Lyon, France'},
  d:{fr:"Du gras-double mariné au vin blanc, pané et grillé, servi avec une sauce gribiche. Le maréchal de Castellane, gouverneur de Lyon et ancien sapeur, aurait donné son surnom à ce morceau plat comme un tablier de cuir.",
     en:"Tripe marinated in white wine, breaded and grilled, served with sauce gribiche. Marshal de Castellane, governor of Lyon and a former sapper, is said to have given his nickname to this cut, flat as a leather apron."},
  i:[['beef_tripe',800,'g'],['white_wine',300,'ml'],['dijon_mustard',3,'tbsp'],['egg',3,'pc'],['breadcrumbs',250,'g'],['butter',100,'g'],['mayonnaise',200,'g'],['pickles',60,'g'],['capers',3,'tbsp'],['tarragon',3,'tbsp'],['chives',3,'tbsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le gras-double déjà cuit 12 heures dans le vin blanc avec sel et poivre.","Épongez-le, tartinez-le de moutarde des deux côtés, puis passez-le dans l'œuf battu et la chapelure.","Laissez la panure sécher 30 minutes au frais : elle tiendra mieux à la cuisson.","Faites cuire au beurre clarifié à feu moyen, 6 minutes par face, jusqu'à ce que la croûte soit dorée et craquante.","Préparez la gribiche en mêlant mayonnaise, œufs durs hachés, cornichons, câpres et herbes. Servez avec un quartier de citron."],
     en:["Marinate the pre-cooked tripe for 12 hours in the white wine with salt and pepper.","Pat it dry, spread mustard on both sides, then coat in beaten egg and breadcrumbs.","Let the crumb dry for 30 minutes in the fridge: it will hold better during cooking.","Cook in clarified butter over medium heat, 6 minutes a side, until the crust is golden and crisp.","Make the gribiche by combining mayonnaise, chopped hard-boiled egg, gherkins, capers and herbs. Serve with a lemon wedge."]} },

{ id:'gratinee-a-l-oignon', c:'eu', lat:48.862, lon:2.345, base:4, prep:20, cook:75, diff:1, tags:['soup','comfort','cheese'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#8f6a4a','#e0b45a','#f2dfa8','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Gratinée à l’oignon',en:'French onion soup'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"La soupe des Halles, avalée brûlante à cinq heures du matin par les forts et les noctambules. Tout tient dans la patience : les oignons doivent fondre une heure entière avant de prendre leur couleur d'acajou.",
     en:"The soup of Les Halles, swallowed scalding at five in the morning by market porters and night owls. It is all patience: the onions must melt for a full hour before they take on their mahogany colour."},
  i:[['onion',1.5,'kg'],['butter',100,'g'],['flour',2,'tbsp'],['beef_broth',1.5,'l'],['white_wine',200,'ml'],['rustic_bread',8,'slice'],['gruyere_cheese',250,'g'],['garlic',2,'clove'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['brandy',40,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Émincez les oignons très finement et faites-les fondre dans le beurre à couvert 30 minutes, sans coloration.","Découvrez et poursuivez 40 minutes en remuant souvent : ils doivent devenir bruns et confits, jamais brûlés.","Singez à la farine, déglacez au vin blanc et au marc, puis mouillez du bouillon chaud.","Ajoutez thym et laurier et laissez frémir 25 minutes ; salez tardivement, le bouillon réduit.","Répartissez dans des bols, posez les croûtons frottés à l'ail, couvrez d'une épaisse couche de gruyère et gratinez 8 minutes sous le gril."],
     en:["Slice the onions very finely and melt them in the butter, covered, for 30 minutes without colouring.","Uncover and continue for 40 minutes, stirring often: they should turn brown and jammy, never burnt.","Dust with flour, deglaze with white wine and marc, then pour in the hot broth.","Add thyme and bay and simmer for 25 minutes; salt late, as the broth reduces.","Divide between bowls, lay on the garlic-rubbed croutons, cover with a thick layer of gruyère and grill for 8 minutes."]} },

{ id:'hachis-parmentier', c:'eu', lat:48.850, lon:2.360, base:6, prep:30, cook:60, diff:1, tags:['beef','comfort','bake'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#e0b45a','#6f4a2a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Hachis Parmentier',en:'Hachis Parmentier'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"De la viande de pot-au-feu hachée sous une purée dorée. Le nom rend hommage à Antoine Parmentier, qui fit accepter la pomme de terre aux Français en la faisant garder par des soldats — pour qu'on la vole.",
     en:"Beef from the pot-au-feu, chopped and topped with golden mash. The name honours Antoine Parmentier, who got the French to accept the potato by having it guarded by soldiers — so that it would be stolen."},
  i:[['beef_chuck',800,'g'],['onion',2,'pc'],['carrot',2,'pc'],['garlic',4,'clove'],['tomato_paste',2,'tbsp'],['beef_broth',300,'ml'],['white_wine',150,'ml'],['potato',1.2,'kg'],['butter',150,'g'],['whole_milk',200,'ml'],['egg_yolk',1,'pc'],['gruyere_cheese',100,'g'],['parsley',4,'tbsp'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire le bœuf 2 heures en pot-au-feu, ou utilisez les restes de la veille — c'est l'esprit du plat.","Hachez-le au couteau, jamais au robot : le hachoir écrase les fibres et rend la farce pâteuse.","Faites fondre oignon, carotte et ail, ajoutez la viande, le concentré, le vin et le bouillon, et laissez compoter 20 minutes.","Écrasez les pommes de terre au presse-purée avec le beurre et le lait chaud, puis liez au jaune d'œuf.","Étalez la viande, couvrez de purée, striez à la fourchette, poudrez de gruyère et enfournez 35 minutes à 200 °C."],
     en:["Cook the beef for 2 hours as a pot-au-feu, or use yesterday's leftovers — that is the spirit of the dish.","Chop it by knife, never in a machine: a blade crushes the fibres and makes the filling pasty.","Soften onion, carrot and garlic, add the meat, tomato paste, wine and broth, and stew for 20 minutes.","Rice the potatoes with the butter and hot milk, then bind with the egg yolk.","Spread the meat, cover with the mash, fork the surface, dust with gruyère and bake for 35 minutes at 200°C."]} },

{ id:'navarin-d-agneau', c:'eu', lat:48.856, lon:2.352, base:6, prep:35, cook:90, diff:2, tags:['lamb','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e0913a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Navarin d’agneau printanier',en:'Spring lamb navarin'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"Un ragoût d'agneau aux légumes nouveaux, tournés un à un et glacés à part pour rester nets. Le nom viendrait du navet, ou de la bataille de Navarin — les cuisiniers n'ont jamais tranché.",
     en:"A lamb stew with spring vegetables, each turned by hand and glazed separately so they stay distinct. The name may come from the turnip, or from the battle of Navarino — cooks have never settled it."},
  i:[['lamb_shoulder',1.5,'kg'],['turnip',600,'g'],['carrot',500,'g'],['pearl_onions',300,'g'],['peas',300,'g'],['green_beans',300,'g'],['potato',600,'g'],['tomato_paste',2,'tbsp'],['flour',3,'tbsp'],['garlic',4,'clove'],['sugar',1,'tbsp'],['butter',60,'g'],['beef_broth',1,'l'],['thyme',3,'sprig'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Saisissez l'agneau en gros morceaux à feu vif, par petites quantités, jusqu'à belle coloration.","Saupoudrez de sucre et laissez caraméliser une minute : c'est ce qui donne à la sauce sa couleur.","Singez à la farine, ajoutez le concentré et l'ail, mouillez de bouillon et laissez mijoter 1 heure.","Tournez les navets et les carottes en olives, glacez-les au beurre et au sucre dans une poêle à part.","Ajoutez pommes de terre et légumes glacés pour les 25 dernières minutes ; les pois et haricots, blanchis, seulement à la fin."],
     en:["Sear the lamb in large pieces over high heat, in small batches, until well coloured.","Sprinkle with sugar and let it caramelise for a minute: this is what gives the sauce its colour.","Dust with flour, add the tomato paste and garlic, pour in the broth and simmer for 1 hour.","Turn the turnips and carrots into olive shapes and glaze them in butter and sugar in a separate pan.","Add the potatoes and glazed vegetables for the last 25 minutes; the blanched peas and beans only at the very end."]} },

{ id:'sole-normande', c:'eu', lat:49.923, lon:1.078, base:4, prep:40, cook:30, diff:3, tags:['sea','festive','sunday'],
  art:{v:'plate',bg:'#26404c',plate:'#f4ecd8',style:'fish',food:['#f4f0e6','#f0e8d0','#e8dcc0','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Sole normande',en:'Sole normande'},
  p:{fr:'Dieppe, Normandie, France',en:'Dieppe, Normandy, France'},
  d:{fr:"Une sole pochée au cidre, couronnée de moules, de crevettes et de champignons sous une sauce à la crème. Créée vers 1830 au Rocher de Cancale à Paris, elle fut le plat qui rendit la cuisine normande célèbre.",
     en:"Sole poached in cider, crowned with mussels, prawns and mushrooms under a cream sauce. Created around 1830 at the Rocher de Cancale in Paris, it was the dish that made Norman cooking famous."},
  i:[['whole_fish',1.2,'kg'],['mussels',800,'g'],['shrimp',300,'g'],['button_mushrooms',250,'g'],['dry_cider',400,'ml'],['heavy_cream',300,'ml'],['butter',150,'g'],['flour',3,'tbsp'],['egg_yolk',2,'pc'],['shallot',3,'pc'],['lemon',1,'pc'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites ouvrir les moules au cidre avec une échalote, 4 minutes, puis décoquillez-les et filtrez le jus à travers un linge.","Levez les filets de sole, roulez-les et rangez-les dans un plat beurré avec le reste des échalotes.","Mouillez du jus de moules filtré, couvrez d'un papier beurré et enfournez 12 minutes à 180 °C.","Récupérez le jus de cuisson, faites-le réduire de moitié, puis liez-le d'un roux blanc et de la crème.","Hors du feu, ajoutez les jaunes et le citron. Nappez les filets, entourez de moules, crevettes et champignons sautés."],
     en:["Open the mussels in the cider with a shallot for 4 minutes, then shell them and strain the liquor through a cloth.","Fillet the sole, roll the fillets and lay them in a buttered dish with the remaining shallots.","Moisten with the strained mussel liquor, cover with buttered paper and bake for 12 minutes at 180°C.","Pour off the cooking juices, reduce them by half, then thicken with a white roux and the cream.","Off the heat, add the yolks and lemon. Coat the fillets and surround them with the mussels, prawns and sautéed mushrooms."]} },

{ id:'andouille-de-vire', c:'eu', lat:48.838, lon:-0.892, base:4, prep:20, cook:20, diff:1, tags:['pork','fresh','fast'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'flat',food:['#3a2a2a','#6f4a4a','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Andouille de Vire et pommes au cidre',en:'Vire andouille with cider apples'},
  p:{fr:'Vire, Normandie, France',en:'Vire, Normandy, France'},
  d:{fr:"Une andouille faite de bandes d'estomac de porc enfilées à la main puis fumée six semaines au bois de hêtre. Servie froide en tranches fines, ou tiède avec des pommes fondues au cidre.",
     en:"An andouille made of strips of pig's stomach threaded by hand and then smoked for six weeks over beech. Served cold in thin slices, or warm with apples softened in cider."},
  i:[['andouille',600,'g'],['apple',6,'pc'],['dry_cider',300,'ml'],['butter',60,'g'],['calvados',40,'ml'],['heavy_cream',150,'ml'],['dijon_mustard',2,'tbsp'],['rustic_bread',8,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez une andouille véritablement fumée, à la robe noire et au grain visible en tranche : les bandes d'estomac doivent se distinguer.","Épluchez les pommes, coupez-les en quartiers épais et faites-les revenir au beurre jusqu'à ce qu'elles blondissent.","Flambez au calvados, mouillez de cidre et laissez réduire de moitié, à couvert.","Ajoutez la crème et la moutarde, et laissez napper 5 minutes.","Poêlez les tranches d'andouille 2 minutes par face, sans excès — elle est déjà cuite — et servez sur les pommes, avec du pain grillé."],
     en:["Choose a genuinely smoked andouille, black-skinned with a visible grain in the slice: the stomach strips should be distinguishable.","Peel the apples, cut them into thick wedges and fry them in butter until golden.","Flame with calvados, moisten with cider and reduce by half, covered.","Add the cream and mustard, and let it coat for 5 minutes.","Fry the andouille slices for 2 minutes a side, no longer — it is already cooked — and serve on the apples, with toast."]} },

{ id:'canard-a-la-rouennaise', c:'eu', lat:49.440, lon:1.093, base:4, prep:45, cook:35, diff:3, tags:['poultry','festive','sunday'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#6f2a2a','#8f3b2a','#c9a878','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Canard à la rouennaise',en:'Duck à la rouennaise'},
  p:{fr:'Rouen, Normandie, France',en:'Rouen, Normandy, France'},
  d:{fr:"Un canard étouffé plutôt que saigné, rôti saignant, dont la carcasse est pressée pour en tirer le sang qui liera la sauce. Le rituel de la presse d'argent, en salle, appartient à la grande cuisine du XIXe siècle.",
     en:"A duck smothered rather than bled, roasted rare, its carcass then pressed to extract the blood that will bind the sauce. The ritual of the silver press, at the table, belongs to the grand cooking of the 19th century."},
  i:[['whole_duck',2,'kg'],['duck_legs',2,'pc'],['red_wine',400,'ml'],['brandy',60,'ml'],['shallot',4,'pc'],['butter',100,'g'],['pate',150,'g'],['lemon',1,'pc'],['thyme',3,'sprig'],['black_peppercorns',1,'tbsp'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rôtissez le canard 20 minutes à 220 °C seulement : la chair doit rester franchement rosée à cœur.","Levez les aiguillettes et les cuisses, réservez-les au chaud, et concassez la carcasse.","Pressez la carcasse — à défaut de presse, écrasez-la fermement dans un tamis — pour recueillir le sang et les sucs.","Faites réduire de moitié le vin rouge avec les échalotes ciselées et le poivre concassé.","Hors du feu, incorporez le foie écrasé, les sucs de carcasse et le beurre en parcelles, sans jamais bouillir. Citronnez et nappez les aiguillettes."],
     en:["Roast the duck for only 20 minutes at 220°C: the flesh must stay frankly pink at the centre.","Carve off the breast slices and legs, keep them warm, and break up the carcass.","Press the carcass — failing a press, crush it firmly in a sieve — to collect the blood and juices.","Reduce the red wine by half with the chopped shallots and cracked pepper.","Off the heat, work in the crushed liver, the carcass juices and the butter in pieces, never boiling. Sharpen with lemon and coat the breast slices."]} },

{ id:'cotriade', c:'eu', lat:47.748, lon:-3.367, base:6, prep:30, cook:45, diff:1, tags:['sea','soup','comfort'],
  art:{v:'pot',bg:'#26404c',plate:'#f2e8d0',style:'fish',food:['#f0e8d0','#e8dcc0','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Cotriade',en:'Cotriade'},
  p:{fr:'Lorient, Bretagne, France',en:'Lorient, Brittany, France'},
  d:{fr:"La soupe des marins bretons, faite à bord avec la part de poisson qui leur revenait. On mange d'abord le bouillon sur du pain, puis le poisson et les pommes de terre arrosés d'une vinaigrette relevée.",
     en:"The soup of Breton sailors, made on board with the share of the catch that was theirs. The broth is eaten first over bread, then the fish and potatoes, dressed with a sharp vinaigrette."},
  i:[['mackerel',600,'g'],['whitefish',600,'g'],['sardines',400,'g'],['potato',1,'kg'],['onion',3,'pc'],['garlic',5,'clove'],['salted_butter',80,'g'],['bay_leaf',3,'pc'],['thyme',3,'sprig'],['white_wine_vinegar',60,'ml'],['dijon_mustard',1,'tbsp'],['olive_oil',80,'ml'],['rustic_bread',8,'slice'],['parsley',5,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites fondre les oignons émincés dans le beurre salé, ajoutez l'ail, le thym et le laurier.","Couvrez de deux litres d'eau, salez, et faites cuire les pommes de terre en gros morceaux 20 minutes.","Ajoutez les poissons du plus ferme au plus fragile, en trois fois, en comptant 5 à 10 minutes chacun.","Retirez poissons et pommes de terre à l'écumoire, tenez-les au chaud sur un plat.","Servez le bouillon en soupe sur des tranches de pain, puis le poisson arrosé d'une vinaigrette moutardée et de persil."],
     en:["Melt the sliced onions in the salted butter, then add the garlic, thyme and bay.","Cover with two litres of water, salt it, and cook the potatoes in large pieces for 20 minutes.","Add the fish from firmest to most delicate, in three stages, allowing 5 to 10 minutes each.","Lift out the fish and potatoes with a slotted spoon and keep them warm on a platter.","Serve the broth as a soup over slices of bread, then the fish dressed with a mustardy vinaigrette and parsley."]} },

{ id:'coquilles-saint-jacques-bretonne', c:'eu', lat:48.514, lon:-2.765, base:4, prep:30, cook:20, diff:2, tags:['sea','festive','bake'],
  art:{v:'plate',bg:'#26404c',plate:'#f4ecd8',style:'fish',food:['#f4f0e6','#e0b45a','#f2dfa8','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Coquilles Saint-Jacques à la bretonne',en:'Breton scallops'},
  p:{fr:'Saint-Brieuc, Bretagne, France',en:'Saint-Brieuc, Brittany, France'},
  d:{fr:"Des noix de Saint-Jacques dans leur coquille, sous une persillade au beurre salé et à la chapelure. La baie de Saint-Brieuc est le premier gisement de France : la pêche y est limitée à quarante-cinq minutes par jour.",
     en:"Scallops in their shell under a parsley crust of salted butter and breadcrumbs. The bay of Saint-Brieuc is France's largest bed: fishing there is limited to forty-five minutes a day."},
  i:[['scallops',16,'pc'],['salted_butter',150,'g'],['shallot',4,'pc'],['garlic',4,'clove'],['parsley',1,'bunch'],['breadcrumbs',100,'g'],['white_wine',150,'ml'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Décoquillez les Saint-Jacques, séparez la noix du corail et lavez soigneusement les coquilles creuses.","Travaillez le beurre salé en pommade avec l'échalote et l'ail hachés très fin, le persil et un peu de citron.","Faites suer les échalotes restantes au vin blanc et laissez réduire à sec.","Déposez une noix et son corail dans chaque coquille, couvrez d'une noix de beurre persillé et saupoudrez de chapelure.","Enfournez 8 minutes à 240 °C, tout en haut du four : les noix doivent rester nacrées à cœur."],
     en:["Shuck the scallops, separate the white from the coral and wash the deep shells thoroughly.","Cream the salted butter with very finely chopped shallot and garlic, the parsley and a little lemon.","Sweat the remaining shallots in white wine and reduce until dry.","Set a scallop and its coral in each shell, cover with a knob of parsley butter and dust with breadcrumbs.","Bake for 8 minutes at 240°C at the top of the oven: the scallops should stay pearly at the centre."]} },

{ id:'gateau-breton', c:'eu', lat:47.658, lon:-2.760, base:8, prep:25, cook:45, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#c98a2c','#f2dfa8','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Gâteau breton',en:'Gâteau breton'},
  p:{fr:'Vannes, Morbihan, France',en:'Vannes, Morbihan, France'},
  d:{fr:"Un gâteau dense de beurre salé et de jaunes d'œufs, quadrillé à la fourchette avant cuisson. Il se conservait des semaines : les marins l'emportaient en mer, où il tenait mieux que le pain.",
     en:"A dense cake of salted butter and egg yolks, cross-hatched with a fork before baking. It kept for weeks: sailors took it to sea, where it lasted better than bread."},
  i:[['flour',300,'g'],['salted_butter',250,'g'],['sugar',250,'g'],['egg_yolk',8,'pc'],['dark_rum',2,'tbsp'],['vanilla',1,'tsp'],['salt',null,'']],
  s:{fr:["Sortez le beurre une heure à l'avance : il doit être pommade, jamais fondu.","Travaillez-le longuement avec le sucre, jusqu'à ce que le mélange blanchisse et double presque de volume.","Incorporez sept jaunes un à un, puis le rhum et la vanille.","Ajoutez la farine et une pincée de sel en soulevant la masse, sans la travailler : le gâteau doit rester sableux.","Étalez dans un moule beurré sur 3 cm, dorez au dernier jaune et tracez des losanges à la fourchette. Enfournez 45 minutes à 170 °C."],
     en:["Take the butter out an hour ahead: it must be soft, never melted.","Beat it at length with the sugar, until the mixture pales and nearly doubles in volume.","Work in seven yolks one at a time, then the rum and vanilla.","Fold in the flour and a pinch of salt, lifting rather than beating: the cake should stay short.","Spread 3 cm deep in a buttered tin, glaze with the last yolk and score diamonds with a fork. Bake for 45 minutes at 170°C."]} },

{ id:'rillons-de-tours', c:'eu', lat:47.394, lon:0.684, base:6, prep:20, cook:180, diff:2, tags:['pork','slow','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a2b','#6f4a2a','#c9a878','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Rillons de Tours',en:'Rillons de Tours'},
  p:{fr:'Tours, Touraine, France',en:'Tours, Touraine, France'},
  d:{fr:"De gros cubes de poitrine confits dans le saindoux puis caramélisés au vin de Vouvray, croustillants dehors et fondants dedans. Balzac, Tourangeau, les cite dans Le Lys dans la vallée comme une madeleine d'enfance.",
     en:"Large cubes of pork belly confited in lard then caramelised in Vouvray wine, crisp outside and melting within. Balzac, a son of Touraine, cites them in Le Lys dans la vallée as a childhood memory."},
  i:[['pork_belly',1.5,'kg'],['coarse_salt',40,'g'],['lard',300,'g'],['white_wine',200,'ml'],['sugar',1,'tbsp'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['garlic',4,'clove'],['pepper',null,'']],
  s:{fr:["Taillez la poitrine avec sa couenne en cubes de 5 cm et salez-les 12 heures au gros sel.","Rincez, épongez soigneusement, puis faites-les colorer sur toutes les faces dans le saindoux fondu.","Baissez le feu au minimum, ajoutez ail, thym et laurier, et laissez confire 2 h 30 à couvert : la graisse ne doit jamais frémir fort.","Retirez le couvercle, montez le feu et laissez la couenne devenir croustillante 15 minutes.","Déglacez au vin blanc avec le sucre, laissez caraméliser en remuant, et servez tièdes, avec une salade de mâche."],
     en:["Cut the belly with its rind into 5 cm cubes and salt them for 12 hours in coarse salt.","Rinse, dry thoroughly, then colour them on all sides in the melted lard.","Turn the heat to its lowest, add garlic, thyme and bay, and confit for 2½ hours covered: the fat must never bubble hard.","Take off the lid, raise the heat and let the rind crisp for 15 minutes.","Deglaze with the white wine and sugar, let it caramelise while stirring, and serve warm with a lamb's lettuce salad."]} },

{ id:'sandre-au-beurre-blanc', c:'eu', lat:47.218, lon:-1.554, base:4, prep:25, cook:20, diff:3, tags:['sea','sunday','fast'],
  art:{v:'plate',bg:'#26404c',plate:'#f4ecd8',style:'fish',food:['#f4f0e6','#f0e8d0','#e8dcc0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Sandre au beurre blanc',en:'Zander with beurre blanc'},
  p:{fr:'Nantes, Pays de la Loire, France',en:'Nantes, Pays de la Loire, France'},
  d:{fr:"Un poisson de Loire sous une émulsion de beurre, d'échalote et de muscadet. Clémence Lefeuvre, cuisinière à Saint-Julien-de-Concelles, aurait inventé le beurre blanc vers 1890 en ratant une béarnaise.",
     en:"A Loire fish under an emulsion of butter, shallot and Muscadet. Clémence Lefeuvre, a cook at Saint-Julien-de-Concelles, is said to have invented beurre blanc around 1890 by botching a béarnaise."},
  i:[['whitefish',800,'g'],['shallot',6,'pc'],['white_wine',150,'ml'],['white_wine_vinegar',80,'ml'],['salted_butter',300,'g'],['heavy_cream',2,'tbsp'],['potato',600,'g'],['chives',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ciselez les échalotes le plus finement possible et faites-les réduire à sec avec le vin et le vinaigre.","Il doit rester deux cuillerées de compotée humide, presque sirupeuse : c'est la base de l'émulsion.","Ajoutez la crème — elle stabilise —, puis incorporez le beurre très froid en dés, un à un, en fouettant hors du feu.","La sauce doit rester tiède : trop chaude, elle tranche ; trop froide, elle fige. Ne la faites jamais bouillir.","Faites cuire les pavés de sandre à la peau 6 minutes, retournez-les une minute, et nappez de beurre blanc."],
     en:["Chop the shallots as finely as you can and reduce them with the wine and vinegar until dry.","Two spoonfuls of moist, almost syrupy compote should remain: that is the base of the emulsion.","Add the cream — it stabilises the sauce — then whisk in the very cold butter, cube by cube, off the heat.","The sauce must stay warm: too hot it splits, too cold it sets. Never let it boil.","Cook the zander fillets skin-side down for 6 minutes, turn for a minute, and coat with the beurre blanc."]} },

{ id:'gateau-nantais', c:'eu', lat:47.213, lon:-1.559, base:8, prep:25, cook:40, diff:1, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#f4f0e6','#e0b45a','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Gâteau nantais',en:'Gâteau nantais'},
  p:{fr:'Nantes, Pays de la Loire, France',en:'Nantes, Pays de la Loire, France'},
  d:{fr:"Un gâteau aux amandes imbibé de rhum et couvert d'un glaçage blanc. Il est né du commerce triangulaire, qui faisait remonter à Nantes le sucre et le rhum des Antilles — une origine que la ville regarde aujourd'hui en face.",
     en:"An almond cake soaked in rum under a white icing. It was born of the triangular trade, which brought sugar and rum from the Caribbean up to Nantes — an origin the city now faces squarely."},
  i:[['butter',150,'g'],['sugar',150,'g'],['almonds',150,'g'],['egg',3,'pc'],['flour',50,'g'],['dark_rum',80,'ml'],['powdered_sugar',150,'g'],['vanilla',1,'tsp'],['salt',null,'']],
  s:{fr:["Travaillez le beurre pommade avec le sucre jusqu'à ce que le mélange blanchisse.","Ajoutez la poudre d'amandes, puis les œufs un à un, la farine, la vanille et la moitié du rhum.","Versez dans un moule beurré et enfournez 40 minutes à 170 °C ; le gâteau doit rester moelleux au centre.","À la sortie du four, piquez-le et imbibez-le du rhum restant, puis laissez-le refroidir dans son moule.","Préparez un glaçage épais avec le sucre glace et une cuillerée d'eau, nappez-en le dessus et laissez sécher deux heures."],
     en:["Cream the softened butter with the sugar until the mixture pales.","Add the ground almonds, then the eggs one at a time, the flour, vanilla and half the rum.","Pour into a buttered tin and bake for 40 minutes at 170°C; the cake should stay moist at the centre.","As it comes out, prick it and soak it with the remaining rum, then let it cool in the tin.","Make a thick icing with the icing sugar and a spoonful of water, spread it over the top and let it set for two hours."]} },

{ id:'mogettes-au-jambon', c:'eu', lat:46.457, lon:-1.165, base:6, prep:20, cook:120, diff:1, tags:['legume','comfort','slow'],
  art:{v:'plate',bg:'#2f3328',plate:'#f0e4c8',style:'stew',food:['#f0e8d0','#e8dcb8','#c9604a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mogettes au jambon',en:'Mogette beans with ham'},
  p:{fr:'Luçon, Vendée, France',en:'Luçon, Vendée, France'},
  d:{fr:"Le haricot blanc de Vendée, cuit à l'eau claire puis servi sous une tranche de jambon grillée, sur une tartine de pain frottée d'ail. Rien d'autre : la mogette a la peau si fine qu'elle fond, et se suffit à elle-même.",
     en:"The white bean of the Vendée, cooked in plain water and served under a grilled slice of ham, on bread rubbed with garlic. Nothing else: the mogette has a skin so fine it melts, and needs no help."},
  i:[['white_beans',600,'g'],['bayonne_ham',6,'slice'],['onion',1,'pc'],['carrot',1,'pc'],['garlic',6,'clove'],['bay_leaf',2,'pc'],['thyme',2,'sprig'],['salted_butter',100,'g'],['rustic_bread',6,'slice'],['heavy_cream',100,'ml'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les mogettes 2 heures seulement — davantage et elles éclateraient.","Mettez-les à l'eau froide non salée avec oignon, carotte, ail, thym et laurier ; salez à mi-cuisson seulement.","Laissez frémir 1 h 30 sans jamais bouillir : un bouillon vif ferait tomber les peaux.","Égouttez en gardant un peu de bouillon, et liez avec le beurre salé et la crème.","Grillez le pain, frottez-le d'ail, posez les mogettes dessus et couronnez d'une tranche de jambon juste saisie."],
     en:["Soak the beans for two hours only — any longer and they would burst.","Put them in cold unsalted water with onion, carrot, garlic, thyme and bay; salt only halfway through.","Simmer for 1½ hours without ever boiling: a hard boil would loosen the skins.","Drain, keeping a little of the liquor, and enrich with the salted butter and cream.","Toast the bread, rub it with garlic, spoon the beans on top and crown with a slice of just-seared ham."]} },

{ id:'cagouilles-charentaise', c:'eu', lat:45.650, lon:0.160, base:6, prep:120, cook:90, diff:2, tags:['slow','festive','comfort'],
  art:{v:'pot',bg:'#2b2a1c',plate:'#f0e4c8',style:'stew',food:['#8f6a4a','#c9a878','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Cagouilles à la charentaise',en:'Charente snails'},
  p:{fr:'Angoulême, Charente, France',en:'Angoulême, Charente, France'},
  d:{fr:"Les escargots petits-gris mijotés à la charentaise, avec du jambon, de la chair à saucisse et beaucoup d'ail. Les Charentais s'appellent eux-mêmes cagouillards : lents comme l'escargot, et fiers de l'être.",
     en:"Small grey snails stewed in the Charente manner, with ham, sausage meat and a great deal of garlic. The people of Charente call themselves cagouillards: slow as the snail, and proud of it."},
  i:[['snails',72,'pc'],['bayonne_ham',150,'g'],['ground_pork',300,'g'],['garlic',12,'clove'],['shallot',4,'pc'],['white_wine',300,'ml'],['ripe_tomato',300,'g'],['flour',2,'tbsp'],['parsley',1,'bunch'],['bay_leaf',3,'pc'],['thyme',3,'sprig'],['olive_oil',80,'ml'],['rustic_bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites jeûner les escargots une semaine, lavez-les à l'eau vinaigrée jusqu'à ce qu'elle reste claire, puis blanchissez-les 10 minutes.","Retirez-les de leur coquille, ôtez le tortillon noir et rincez-les une dernière fois.","Faites revenir le jambon en dés, la chair à saucisse et les échalotes dans l'huile, singez à la farine.","Ajoutez les escargots, l'ail écrasé, la tomate, le vin blanc, le thym et le laurier ; couvrez d'eau à hauteur.","Laissez mijoter 1 h 15 à feu doux, ajoutez une grande quantité de persil et servez avec du pain de campagne."],
     en:["Starve the snails for a week, wash them in vinegared water until it runs clear, then blanch them for 10 minutes.","Take them from their shells, remove the black coil and rinse once more.","Fry the diced ham, sausage meat and shallots in the oil, then dust with flour.","Add the snails, crushed garlic, tomato, white wine, thyme and bay; cover with water.","Simmer for 1¼ hours over low heat, add a great deal of parsley and serve with country bread."]} },

{ id:'ttoro', c:'eu', lat:43.389, lon:-1.663, base:6, prep:35, cook:45, diff:2, tags:['sea','soup','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f2e8d0',style:'fish',food:['#c9402c','#e0913a','#f0e4c0','#8f3b2a'],garnish:'#6fbf8f'},
  n:{fr:'Ttoro',en:'Ttoro'},
  p:{fr:'Saint-Jean-de-Luz, Pays basque, France',en:'Saint-Jean-de-Luz, Basque Country, France'},
  d:{fr:"La soupe de poisson des morutiers basques, relevée au piment d'Espelette et épaissie de pain. On la préparait à bord avec les têtes de merlu et les carcasses ; à terre, elle est devenue un plat de fête.",
     en:"The fish soup of Basque cod fishermen, sharpened with Espelette pepper and thickened with bread. Made on board with hake heads and bones; ashore, it became a feast dish."},
  i:[['whitefish',1,'kg'],['mussels',600,'g'],['shrimp',400,'g'],['fish_broth',1.5,'l'],['onion',3,'pc'],['garlic',6,'clove'],['ripe_tomato',500,'g'],['green_pepper',2,'pc'],['espelette_pepper',2,'tsp'],['white_wine',250,'ml'],['stale_bread',150,'g'],['olive_oil',100,'ml'],['parsley',5,'tbsp'],['salt',null,'']],
  s:{fr:["Faites un fumet avec les têtes et les arêtes de merlu, 30 minutes, puis filtrez-le en pressant.","Faites fondre oignons, ail et poivrons dans l'huile, ajoutez les tomates concassées et laissez réduire 20 minutes.","Mouillez du fumet et du vin blanc, ajoutez le piment d'Espelette et le pain rassis émietté ; laissez épaissir 15 minutes.","Pochez les tronçons de merlu 8 minutes dans ce bouillon, sans le laisser bouillir.","Ajoutez moules et crevettes, couvrez 4 minutes le temps que les coquilles s'ouvrent, et couvrez de persil."],
     en:["Make a stock with the hake heads and bones for 30 minutes, then strain it, pressing well.","Soften the onions, garlic and peppers in the oil, add the crushed tomatoes and reduce for 20 minutes.","Moisten with the stock and white wine, add the Espelette pepper and crumbled stale bread; thicken for 15 minutes.","Poach the hake sections for 8 minutes in this broth, without letting it boil.","Add the mussels and prawns, cover for 4 minutes until the shells open, and cover with parsley."]} }
];
